const SCHEDULE={0:{day:"Sunday",open:7,close:20,openStr:"7:00 AM",closeStr:"8:00 PM"},1:{day:"Monday",open:6,close:21,openStr:"6:00 AM",closeStr:"9:00 PM"},2:{day:"Tuesday",open:6,close:21,openStr:"6:00 AM",closeStr:"9:00 PM"},3:{day:"Wednesday",open:6,close:21,openStr:"6:00 AM",closeStr:"9:00 PM"},4:{day:"Thursday",open:6,close:21,openStr:"6:00 AM",closeStr:"9:00 PM"},5:{day:"Friday",open:6,close:21,openStr:"6:00 AM",closeStr:"9:00 PM"},6:{day:"Saturday",open:6,close:21,openStr:"6:00 AM",closeStr:"9:00 PM"}};function updateLiveStatus(){const e=document.getElementById("live-operating-status");if(!e)return;const t=new Date,s=t.getDay(),o=t.getHours()+t.getMinutes()/60,n=SCHEDULE[s];if(o>=n.open&&o<n.close)e.className="topstrip-status status-open",e.innerHTML=`● Open now <span class="topstrip-sep">·</span> Closes at ${n.closeStr}`;else{let t=o>=n.close?(s+1)%7:s,a=SCHEDULE[t];e.className="topstrip-status status-closed",e.innerHTML=`○ Closed now <span class="topstrip-sep">·</span> Opens ${a.day} at ${a.openStr}`}}document.addEventListener("DOMContentLoaded",()=>{updateLiveStatus(),setInterval(updateLiveStatus,6e4)});